6	// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────
7	
8	export interface PerdasEntry {
9	  val: number;        // valor_estimado
10	  qty: number;        // quantidade
11	  prod: string;       // produto_nome_perda
12	  store: string;      // stores?.nome
13	  date: string | null;
14	  motivo_perda: string;
15	  unidade?: string | null;
16	}
17	
18	export interface PerdasAggregate {
19	  totalValue: number;
20	  totalRecords: number;
21	  /** totalValue / totalRecords, 0 se vazio */
22	  ticketMedio: number;
23	  /** produto com maior totalValue, "-" se vazio */
24	  produtoCritico: string;
25	  /** ordenado por value desc */
26	  byMotivo: Array<{ motivo: string; count: number; value: number; pct: number }>;
27	  /** top 10 por valor, rank 1-10 */
28	  top10Produtos: Array<{ rank: number; produto: string; qty: number; value: number }>;
29	}
30	
31	export interface GeneratePerdasPdfParams {
32	  entries: PerdasEntry[];
33	  periodoLabel: string;       // ex: "01/05/2026 – 31/05/2026"
34	  lojaLabel: string;          // ex: "Momma Asa Sul" ou "Todas as lojas"
35	  motivosLabel: string;       // ex: "Vencido, Quebra" ou "Todos"
36	  dividirEmSemanas?: boolean; // default false
37	  dateStart?: string;         // yyyy-MM-dd — necessário se dividirEmSemanas=true
38	  dateEnd?: string;           // yyyy-MM-dd
39	}
40	
41	interface WeekBucket {
42	  index: number;          // 1, 2, 3...
43	  label: string;          // "Semana 1 — 01/05 a 07/05/2026"
44	  trendLabel: string;     // "S1" para eixo X do gráfico de tendência
45	  trendSubLabel: string;  // "01-07/05" linha de baixo do eixo
46	  start: Date;
47	  end: Date;
48	  entries: PerdasEntry[];
49	  aggregate: PerdasAggregate;
50	}
51	
52	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
53	
54	export function aggregatePerdas(entries: PerdasEntry[]): PerdasAggregate {
55	  if (entries.length === 0) {
56	    return {
57	      totalValue: 0,
58	      totalRecords: 0,
59	      ticketMedio: 0,
60	      produtoCritico: '-',
61	      byMotivo: [],
62	      top10Produtos: [],
63	    };
64	  }
65	
66	  const totalValue = entries.reduce((s, e) => s + e.val, 0);
67	  const totalRecords = entries.length;
68	
69	  // Agrega por motivo
70	  const motivoMap = new Map<string, { count: number; value: number }>();
71	  for (const e of entries) {
72	    const m = e.motivo_perda || 'Não Informado';
73	    const cur = motivoMap.get(m) ?? { count: 0, value: 0 };
74	    motivoMap.set(m, { count: cur.count + 1, value: cur.value + e.val });
75	  }
76	
77	  const byMotivo = Array.from(motivoMap.entries())
78	    .map(([motivo, d]) => ({
79	      motivo,
80	      count: d.count,
81	      value: d.value,
82	      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
83	    }))
84	    .sort((a, b) => b.value - a.value);
85	
86	  // Agrega por produto (valor e qtd)
87	  const prodMap = new Map<string, { qty: number; value: number }>();
88	  for (const e of entries) {
89	    const p = e.prod || 'Desconhecido';
90	    const cur = prodMap.get(p) ?? { qty: 0, value: 0 };
91	    prodMap.set(p, { qty: cur.qty + e.qty, value: cur.value + e.val });
92	  }
93	
94	  const sortedProds = Array.from(prodMap.entries())
95	    .sort((a, b) => b[1].value - a[1].value);
96	
97	  const produtoCritico = sortedProds.length > 0 ? sortedProds[0][0] : '-';
98	
99	  const top10Produtos = sortedProds.slice(0, 10).map(([produto, d], i) => ({
100	    rank: i + 1,
101	    produto,
102	    qty: d.qty,
103	    value: d.value,
104	  }));
105	
106	  return {
107	    totalValue,
108	    totalRecords,
109	    ticketMedio: totalRecords > 0 ? totalValue / totalRecords : 0,
110	    produtoCritico,
111	    byMotivo,
112	    top10Produtos,
113	  };
114	}
115	
116	export interface WeekRange {
117	  index: number;
118	  label: string;        // "Semana 1 — 01/05 a 07/05/2026"
119	  trendLabel: string;   // "S1"
120	  trendSubLabel: string;// "01-07/05"
121	  start: Date;
122	  end: Date;
123	}
124	
125	/** Calcula os intervalos semanais (buckets de 7 dias) de start até end (inclusive). */
126	export function computeWeekRanges(start: Date, end: Date): WeekRange[] {
127	  const ranges: WeekRange[] = [];
128	  let cursor = new Date(start);
129	  let index = 1;
130	
131	  while (cursor <= end) {
132	    const bs = new Date(cursor);
133	    const be = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));
134	
135	    const startFmt = format(bs, 'dd/MM', { locale: ptBR });
136	    const endFmt = format(be, 'dd/MM/yyyy', { locale: ptBR });
137	    const trendSubLabel = `${format(bs, 'dd', { locale: ptBR })}-${format(be, 'dd/MM', { locale: ptBR })}`;
138	
139	    ranges.push({
140	      index,
141	      label: `Semana ${index} — ${startFmt} a ${endFmt}`,
142	      trendLabel: `S${index}`,
143	      trendSubLabel,
144	      start: bs,
145	      end: be,
146	    });
147	
148	    cursor = addDays(be, 1);
149	    index++;
150	  }
151	
152	  return ranges;
153	}
154	
155	/** Divide entries em buckets de 7 dias a partir de start até end (inclusive). */
156	export function splitIntoWeeks(
157	  entries: PerdasEntry[],
158	  start: Date,
159	  end: Date,
160	): WeekBucket[] {
161	  return computeWeekRanges(start, end).map(range => {
162	    const bucketStart = new Date(range.start);
163	    bucketStart.setHours(0, 0, 0, 0);
164	    const bucketEnd = new Date(range.end);
165	    bucketEnd.setHours(23, 59, 59, 999);
166	
167	    const bucketEntries = entries.filter(e => {
168	      if (!e.date) return false;
169	      const d = new Date(e.date);
170	      return d >= bucketStart && d <= bucketEnd;
171	    });
172	
173	    return {
174	      index: range.index,
175	      label: range.label,
176	      trendLabel: range.trendLabel,
177	      trendSubLabel: range.trendSubLabel,
178	      start: range.start,
179	      end: range.end,
180	      entries: bucketEntries,
181	      aggregate: aggregatePerdas(bucketEntries),
182	    };
183	  });
184	}
185	
186	// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
187	// Replicados (não importados de outra feature) para respeitar boundaries FSD.
188	
189	const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
190	const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
191	const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];
192	
193	const currencyFmt = (v: number): string =>
194	  v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
195	
196	const pctFmt = (v: number): string =>
197	  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
198	
199	const qtyFmt = (v: number): string =>
200	  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
201	
202	const loadImage = (url: string): Promise<HTMLImageElement> =>
203	  new Promise((resolve, reject) => {
204	    const img = new Image();
205	    img.crossOrigin = 'Anonymous';
206	    img.onload = () => resolve(img);
207	    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
208	    img.src = url;
209	  });
210	
211	/**
212	 * Garante espaço vertical suficiente. Se não couber, vira página e retorna 52.
213	 */
214	function ensureSpace(
215	  doc: jsPDF,
216	  cursorY: number,
217	  neededMm: number,
218	  pageHeight: number,
219	  drawPageExtras: (hookData: { pageNumber?: number }) => void,
220	): number {
221	  if (cursorY + neededMm > pageHeight - 22) {
222	    doc.addPage();
223	    drawPageExtras({ pageNumber: doc.getNumberOfPages() });
224	    return 52;
225	  }
226	  return cursorY;
227	}
228	
229	/**
230	 * Desenha barras horizontais para uma lista de itens.
231	 * Retorna o Y após o último elemento.
232	 */
233	function drawHorizontalBars(
234	  doc: jsPDF,
235	  items: Array<{ label: string; value: number; displayValue: string }>,
236	  x: number,
237	  y: number,
238	  totalWidth: number,
239	  barHeight = 4.5,
240	  gap = 2.5,
241	  barColor: [number, number, number] = MOMMA_GREEN,
242	): number {
243	  if (items.length === 0) return y;
244	
245	  const maxVal = Math.max(...items.map(i => i.value), 1);
246	  const labelWidth = 30;
247	  const valueWidth = 22;
248	  const barAreaWidth = totalWidth - labelWidth - valueWidth;
249	  let curY = y;
250	
251	  for (const item of items) {
252	    // Label (max 15 chars)
253	    const labelTxt = item.label.length > 15 ? item.label.substring(0, 14) + '…' : item.label;
254	    doc.setFont('helvetica', 'normal');
255	    doc.setFontSize(7);
256	    doc.setTextColor(80, 80, 80);
257	    doc.text(labelTxt, x, curY + barHeight - 1);
258	
259	    const barX = x + labelWidth;
260	
261	    // Background bar
262	    doc.setFillColor(235, 235, 235);
263	    doc.rect(barX, curY, barAreaWidth, barHeight, 'F');
264	
265	    // Colored bar (proportional)
266	    if (item.value > 0) {
267	      const filledW = Math.max(1, (item.value / maxVal) * barAreaWidth);
268	      doc.setFillColor(...barColor);
269	      doc.rect(barX, curY, filledW, barHeight, 'F');
270	    }
271	
272	    // Value label (right)
273	    doc.setFont('helvetica', 'bold');
274	    doc.setFontSize(7);
275	    doc.setTextColor(...MOMMA_GREEN_DARK);
276	    doc.text(item.displayValue, x + totalWidth, curY + barHeight - 1, { align: 'right' });
277	
278	    curY += barHeight + gap;
279	  }
280	
281	  return curY;
282	}
283	
284	/**
285	 * Desenha barras verticais para dados de tendência.
286	 */
287	function drawVerticalBars(
288	  doc: jsPDF,
289	  items: Array<{ trendLabel: string; trendSubLabel: string; value: number; displayValue: string }>,
290	  x: number,
291	  y: number,
292	  chartWidth: number,
293	  chartHeight: number,
294	  barColor: [number, number, number] = MOMMA_GREEN,
295	): void {
296	  if (items.length === 0) return;
297	
298	  const hasData = items.some(i => i.value > 0);
299	  if (!hasData) return;
300	
301	  const maxVal = Math.max(...items.map(i => i.value), 1);
302	  const n = items.length;
303	  const slotW = chartWidth / n;
304	  const barW = slotW * 0.6;
305	  const axisLabelH = 12; // height reserved below chart for labels
306	  const drawH = chartHeight - axisLabelH;
307	
308	  // Baseline
309	  doc.setDrawColor(200, 200, 200);
310	  doc.setLineWidth(0.3);
311	  doc.line(x, y + drawH, x + chartWidth, y + drawH);
312	
313	  for (let i = 0; i < items.length; i++) {
314	    const item = items[i];
315	    const slotX = x + i * slotW;
316	    const barX = slotX + (slotW - barW) / 2;
317	    const barH = item.value > 0 ? Math.max(1, (item.value / maxVal) * drawH) : 0;
318	    const barY = y + drawH - barH;
319	
320	    // Draw bar
321	    if (barH > 0) {
322	      doc.setFillColor(...barColor);
323	      doc.rect(barX, barY, barW, barH, 'F');
324	    }
325	
326	    // Value label above bar (only if bar is tall enough)
327	    if (barH > 6) {
328	      doc.setFont('helvetica', 'bold');
329	      doc.setFontSize(6);
330	      doc.setTextColor(...MOMMA_GREEN_DARK);
331	      doc.text(item.displayValue, barX + barW / 2, barY - 1, { align: 'center' });
332	    }
333	
334	    // Axis labels below baseline
335	    const labelCenterX = slotX + slotW / 2;
336	    doc.setFont('helvetica', 'bold');
337	    doc.setFontSize(7);
338	    doc.setTextColor(80, 80, 80);
339	    doc.text(item.trendLabel, labelCenterX, y + drawH + 5, { align: 'center' });
340	
341	    doc.setFont('helvetica', 'normal');
342	    doc.setFontSize(6);
343	    doc.setTextColor(120, 120, 120);
344	    doc.text(item.trendSubLabel, labelCenterX, y + drawH + 10, { align: 'center' });
345	  }
346	}
347	
348	// ───────────────────────── GERADOR DE PDF ─────────────────────────
349	
350	export async function generatePerdasPdf(params: GeneratePerdasPdfParams): Promise<void> {
351	  const { entries, periodoLabel, lojaLabel, motivosLabel, dividirEmSemanas = false, dateStart, dateEnd } = params;
352	  const agg = aggregatePerdas(entries);
353	
354	  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(() => null);
355	  const watermarkLogo = await loadImage('/logo sistema/android-chrome-512x512.png').catch(() => null);
356	
357	  const doc = new jsPDF('p', 'mm', 'a4');
358	  const pageWidth = doc.internal.pageSize.getWidth();
359	  const pageHeight = doc.internal.pageSize.getHeight();
360	
361	  const subtitulo = dividirEmSemanas ? 'ANÁLISE SEMANAL' : 'ANÁLISE ESTRATÉGICA';
362	
363	  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
364	  const drawPageExtras = (hookData: { pageNumber?: number }) => {
365	    const currentPage = hookData.pageNumber || 1;
366	
367	    // Bordas premium (dupla linha)
368	    doc.setDrawColor(...MOMMA_GREEN);
369	    doc.setLineWidth(0.5);
370	    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
371	    doc.setLineWidth(0.2);
372	    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');
373	
374	    // Logo cabeçalho — preserva aspect ratio, max 18mm altura
375	    if (logoHeader) {
376	      const ratio = logoHeader.height / logoHeader.width;
377	      let expectedWidth = 45;
378	      let expectedHeight = expectedWidth * ratio;
379	      if (expectedHeight > 18) {
380	        expectedHeight = 18;
381	        expectedWidth = expectedHeight / ratio;
382	      }
383	      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
384	    }
385	
386	    // Título e subtítulo (alinhados à direita)
387	    doc.setFont('helvetica', 'bold');
388	    doc.setTextColor(...MOMMA_GREEN_DARK);
389	    doc.setFontSize(16);
390	    doc.text('RELATÓRIO DE PERDAS', pageWidth - 15, 20, { align: 'right' });
391	
392	    doc.setFont('helvetica', 'normal');
393	    doc.setFontSize(9);
394	    doc.setTextColor(...MOMMA_GREEN);
395	    doc.text(subtitulo, pageWidth - 15, 25, { align: 'right' });
396	
397	    doc.setTextColor(...MOMMA_GREEN_SOFT);
398	    doc.setFontSize(8);
399	    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
400	    doc.text(`Loja: ${lojaLabel}`, pageWidth - 15, 35, { align: 'right' });
401	    doc.text(`Motivos: ${motivosLabel}`, pageWidth - 15, 39, { align: 'right' });
402	
403	    // Linha separadora abaixo do header
404	    doc.setDrawColor(...MOMMA_GREEN);
405	    doc.setLineWidth(0.5);
406	    doc.line(15, 43, pageWidth - 15, 43);
407	
408	    // Footer com paginação
409	    doc.setFont('helvetica', 'normal');
410	    doc.setFontSize(8);
411	    doc.setTextColor(...MOMMA_GREEN);
412	    const totalPages = doc.getNumberOfPages();
413	    doc.text(
414	      `Relatório de Perdas Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
415	      pageWidth / 2,
416	      pageHeight - 12,
417	      { align: 'center' },
418	    );
419	
420	    // Watermark sutil ao centro
421	    if (watermarkLogo) {
422	      try {
423	        doc.setGState(new GState({ opacity: 0.08 }));
424	        const wSize = 200;
425	        doc.addImage(
426	          watermarkLogo,
427	          'PNG',
428	          (pageWidth - wSize) / 2,
429	          (pageHeight - wSize) / 2,
430	          wSize,
