873	
874	export interface PerdasGeralEntry {
875	  val: number;             // valor_estimado
876	  store: string;           // nome da loja
877	  loja_id: number | null;
878	  date: string | null;     // data_identificacao (ISO)
879	}
880	
881	export interface GeneratePerdasGeralPdfParams {
882	  entries: PerdasGeralEntry[];  // TODAS as lojas, filtrado só por período
883	  periodoLabel: string;
884	  dateStart: string;            // yyyy-MM-dd
885	  dateEnd: string;              // yyyy-MM-dd
886	  unidades?: string[];          // nomes das unidades selecionadas — para sempre aparecerem, mesmo zeradas
887	}
888	
889	export interface GeralStoreRow {
890	  store: string;
891	  value: number;
892	  count: number;
893	  pct: number;   // % do total do período (0 se total=0)
894	}
895	
896	export interface GeralAggregate {
897	  totalValue: number;
898	  totalRecords: number;
899	  storeCount: number;           // lojas distintas com value > 0
900	  lojaCritica: string;          // loja de maior valor ("-" se vazio)
901	  concentracao: number;         // pct da loja crítica
902	  byStore: GeralStoreRow[];     // ordenado por value desc
903	}
904	
905	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
906	
907	export function aggregateGeral(entries: PerdasGeralEntry[], seedStores?: string[]): GeralAggregate {
908	  const totalValue = entries.reduce((s, e) => s + e.val, 0);
909	  const totalRecords = entries.length;
910	
911	  const storeMap = new Map<string, { value: number; count: number }>();
912	  for (const e of entries) {
913	    const name = e.store && e.store.trim() ? e.store : 'Sem loja';
914	    const cur = storeMap.get(name) ?? { value: 0, count: 0 };
915	    storeMap.set(name, { value: cur.value + e.val, count: cur.count + 1 });
916	  }
917	
918	  // Seed: garante que toda unidade selecionada apareça, mesmo zerada no período.
919	  if (seedStores) {
920	    for (const name of seedStores) {
921	      if (!storeMap.has(name)) storeMap.set(name, { value: 0, count: 0 });
922	    }
923	  }
924	
925	  const byStore: GeralStoreRow[] = Array.from(storeMap.entries())
926	    .map(([store, d]) => ({
927	      store,
928	      value: d.value,
929	      count: d.count,
930	      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
931	    }))
932	    .sort((a, b) => b.value - a.value);
933	
934	  const storeCount = byStore.filter(s => s.value > 0).length;
935	  const lojaCritica = byStore.length > 0 ? byStore[0].store : '-';
936	  const concentracao = byStore.length > 0 ? byStore[0].pct : 0;
937	
938	  return {
939	    totalValue,
940	    totalRecords,
941	    storeCount,
942	    lojaCritica,
943	    concentracao,
944	    byStore,
945	  };
946	}
