948	/** Filtra entries cujo `date` cai dentro do range [start, end] (dia inteiro). */
949	function entriesInRange(entries: PerdasGeralEntry[], start: Date, end: Date): PerdasGeralEntry[] {
950	  const s = new Date(start); s.setHours(0, 0, 0, 0);
951	  const e = new Date(end); e.setHours(23, 59, 59, 999);
952	  return entries.filter(en => {
953	    if (!en.date) return false;
954	    const d = new Date(en.date);
955	    return d >= s && d <= e;
956	  });
957	}
