975	
976	  const maxVal = Math.max(...items.map(i => i.value), 1);
977	  const labelWidth = 40;
978	  const valueWidth = 28;
979	  const barArea = totalWidth - labelWidth - valueWidth;
980	  let curY = y;
981	
982	  for (const item of items) {
983	    // Label (nome da loja, max 22 chars)
984	    const labelTxt = item.store.length > 22 ? item.store.substring(0, 21) + '…' : item.store;
985	    doc.setFont('helvetica', 'normal');
986	    doc.setFontSize(7.5);
987	    doc.setTextColor(70, 70, 70);
988	    doc.text(labelTxt, x, curY + barHeight - 1.5);
989	
990	    const barX = x + labelWidth;
991	
992	    // Background bar
993	    doc.setFillColor(235, 235, 235);
994	    doc.rect(barX, curY, barArea, barHeight, 'F');
995	
996	    if (item.value > 0) {
